#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

typedef long long ll;

int main() {
    int d, n, m;
    while (scanf("%d", &d), d) {
        scanf("%d%d", &n, &m);
        vector<int> x(n + 1), c(m);
        x[0] = 0;
        for (int i = 1; i < n; i++) scanf("%d", &x[i]);
        for (int i = 0; i < m; i++) scanf("%d", &c[i]);

        x[n] = d;
        sort(x.begin(), x.end());
        int res = 0;
        for (int i = 0; i < m; i++) {
            auto lb = lower_bound(x.begin(), x.end(), c[i]);
            if (c[i] != 0) res += min(lb[0] - c[i], c[i] - lb[-1]);
        }
        printf("%d\n", res);
    }
}

