#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

int main() {
    int d;
    while (scanf("%d", &d), d) {
        int n, m;
        scanf("%d%d", &n, &m);
        vector<int> x(n + 1);
        x[0] = 0;

        // Combined input for n and m, optimizing single read
        for (int i = 1; i < n; i++) {
            scanf("%d", &x[i]);
        }
        vector<int> c(m);
        for (int i = 0; i < m; i++) {
            scanf("%d", &c[i]);
        }

        // Optimize the creation of vector p by reserving space
        vector<int> p;
        p.reserve(n + 1);
        p.insert(p.end(), x.begin(), x.end());
        p.push_back(d);
        sort(p.begin(), p.end());

        ll res = 0;
        for (int i = 0; i < m; i++) {
            auto lb = lower_bound(p.begin(), p.end(), c[i]);
            if (c[i] != 0) res += min(*lb - c[i], c[i] - *(lb - 1));
        }
        printf("%lld\n", res); // use printf for better performance
    }
}

